import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const b=JSON.parse('{"title":"Bill Reimbursements","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/11-bill-reimbursement-guide.md","filePath":"v1/en/guide/11-bill-reimbursement-guide.md"}'),n={name:"v1/en/guide/11-bill-reimbursement-guide.md"};function s(o,e,l,u,m,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="bill-reimbursements" tabindex="-1">Bill Reimbursements <a class="header-anchor" href="#bill-reimbursements" aria-label="Permalink to &quot;Bill Reimbursements&quot;">​</a></h1><h2 id="_1-what-this-feature-is" tabindex="-1">1. What this feature is <a class="header-anchor" href="#_1-what-this-feature-is" aria-label="Permalink to &quot;1. What this feature is&quot;">​</a></h2><p>Reimbursement is used for cases where you first pay an expense and later get the money paid back by someone else or by your company (for example, travel, office supplies, or out-of-pocket expenses).</p><p>In Koala, the core logic is:</p><ul><li>You record an <strong>expense</strong> and mark it as <strong>reimbursable</strong></li><li>When it is reimbursed, Koala automatically creates a <strong>Reimbursement Income</strong> bill and adds the reimbursed amount back into the account you choose</li></ul><p>Benefits:</p><ul><li>The original expense is preserved (easy to trace what the money was for)</li><li>The reimbursement payout is recorded (easy to reconcile the deposit account and date)</li><li>Statistics stay clear: the expense and the reimbursement income are recorded separately</li></ul><h2 id="_2-when-to-use-it" tabindex="-1">2. When to use it <a class="header-anchor" href="#_2-when-to-use-it" aria-label="Permalink to &quot;2. When to use it&quot;">​</a></h2><ul><li>Company reimbursements (transportation, hotels, meals, office supplies, etc.)</li><li>Someone paid on your behalf and later transferred money back to you</li><li>Any expense you paid upfront that needs to be recovered later</li></ul><h2 id="_3-how-to-use-it" tabindex="-1">3. How to use it <a class="header-anchor" href="#_3-how-to-use-it" aria-label="Permalink to &quot;3. How to use it&quot;">​</a></h2><h3 id="_3-1-create-a-reimbursable-expense" tabindex="-1">3.1 Create a reimbursable expense <a class="header-anchor" href="#_3-1-create-a-reimbursable-expense" aria-label="Permalink to &quot;3.1 Create a reimbursable expense&quot;">​</a></h3><ol><li>Create a new expense bill</li><li>On the create/edit page, enable <strong>Reimbursement</strong> (or similar options like “Reimbursable / Pending reimbursement”)</li><li>After saving, the bill will show a status such as <strong>Pending reimbursement</strong> / <strong>Reimbursed</strong> in the list</li></ol><h3 id="_3-2-reimburse-an-expense" tabindex="-1">3.2 Reimburse an expense <a class="header-anchor" href="#_3-2-reimburse-an-expense" aria-label="Permalink to &quot;3.2 Reimburse an expense&quot;">​</a></h3><ol><li>In the bill list, find an expense that is <strong>Pending reimbursement</strong></li><li>Swipe left on the bill and select <strong>Reimburse</strong></li><li>On the reimbursement page, set: <ul><li>Amount: defaults to the original expense amount; change it to the actual reimbursed amount if needed</li><li>Date: defaults to today; change it to the actual deposit date if needed</li><li>Deposit account: choose the account that the reimbursement was paid into</li><li>Note: optional</li></ul></li><li>Tap <strong>Done/Save</strong></li></ol><p>After saving, a new <strong>Reimbursement Income</strong> bill will be added to record the payout.</p><h2 id="_4-rules-and-notes" tabindex="-1">4. Rules and notes <a class="header-anchor" href="#_4-rules-and-notes" aria-label="Permalink to &quot;4. Rules and notes&quot;">​</a></h2><ul><li>Only <strong>expenses</strong> that are marked as <strong>reimbursable</strong> can be reimbursed.</li><li>Bill splitting and reimbursements are mutually exclusive: split bills (including split sub-bills and split containers) can’t start the reimbursement flow; reimbursable expenses can’t be split. Decide whether reimbursement is needed first. If necessary, split the cost first, then record the reimbursable part as a separate reimbursable expense.</li><li>Once a <strong>Reimbursement Income</strong> record has been created, the original expense typically can’t be reimbursed again (to avoid double deposits).</li><li>If you delete the <strong>Reimbursement Income</strong> record, the original expense returns to <strong>Pending reimbursement</strong> (and can be reimbursed again).</li><li>Reimbursement income is counted as income in statistics, while the original expense is still counted as expense. This keeps cash flow clear and traceable.</li></ul><h2 id="_5-faq" tabindex="-1">5. FAQ <a class="header-anchor" href="#_5-faq" aria-label="Permalink to &quot;5. FAQ&quot;">​</a></h2><h3 id="q1-what-s-the-difference-between-reimbursement-and-refund" tabindex="-1">Q1: What’s the difference between reimbursement and refund? <a class="header-anchor" href="#q1-what-s-the-difference-between-reimbursement-and-refund" aria-label="Permalink to &quot;Q1: What’s the difference between reimbursement and refund?&quot;">​</a></h3><ul><li>Refund: a return that offsets the original bill (implemented by adding a negative-amount record)</li><li>Reimbursement: getting money back for a reimbursable expense (implemented by adding a Reimbursement Income record)</li></ul><h3 id="q2-what-if-the-reimbursement-was-paid-into-a-different-account" tabindex="-1">Q2: What if the reimbursement was paid into a different account? <a class="header-anchor" href="#q2-what-if-the-reimbursement-was-paid-into-a-different-account" aria-label="Permalink to &quot;Q2: What if the reimbursement was paid into a different account?&quot;">​</a></h3><p>On the reimbursement page, set the <strong>Deposit account</strong> to the actual account that received the money.</p><h3 id="q3-how-do-i-record-a-partial-reimbursement" tabindex="-1">Q3: How do I record a partial reimbursement? <a class="header-anchor" href="#q3-how-do-i-record-a-partial-reimbursement" aria-label="Permalink to &quot;Q3: How do I record a partial reimbursement?&quot;">​</a></h3><p>Change the reimbursement amount to the amount actually reimbursed. The remaining unreimbursed part stays on the original expense for later follow-up.</p>',24)])])}const c=t(n,[["render",s]]);export{b as __pageData,c as default};
